// MarshalCOBOL writes this PX-FILE-TRAILER into w, in the order docs/ir/SPEC.md
// resolved its items, emitting the bytes retained for every slack node and
// every unnamed item it carries, and zero bytes for one it does not.
//
// It is codec's Marshaler. Two values are the descriptor's rather than the
// caller's and are supplied rather than taken from the record: an OCCURS
// DEPENDING ON count is emitted as the number of occurrences written, and
// slack — and the bytes of an item the copybook gives no data-name — is
// emitted as what was retained for it. Everything else is the caller's,
// including the value a discriminator tests — a writer evaluates a predicate
// and never inverts one.
func (p *PxFileTrailer) MarshalCOBOL(w *codec.Writer) error {
	var err error

	if err = w.WriteAlphanumeric(p.FtrRecordType, 3); err != nil {
		return fmt.Errorf("PX-FILE-TRAILER: writing FTR-RECORD-TYPE: %w", err)
	}

	if err = w.WriteZonedInt32(p.FtrCycleDate, 8, codec.SignUnsigned); err != nil {
		return fmt.Errorf("PX-FILE-TRAILER: writing FTR-CYCLE-DATE: %w", err)
	}

	if err = w.WriteZonedInt32(p.FtrPolicyCount, 9, codec.SignUnsigned); err != nil {
		return fmt.Errorf("PX-FILE-TRAILER: writing FTR-POLICY-COUNT: %w", err)
	}

	if err = w.WriteZonedInt32(p.FtrDetailCount, 9, codec.SignUnsigned); err != nil {
		return fmt.Errorf("PX-FILE-TRAILER: writing FTR-DETAIL-COUNT: %w", err)
	}

	if err = w.WritePackedInt64(p.FtrWrittenPremium, 15, codec.Signed); err != nil {
		return fmt.Errorf("PX-FILE-TRAILER: writing FTR-WRITTEN-PREMIUM: %w", err)
	}

	if err = w.WritePackedInt64(p.FtrPaidLoss, 15, codec.Signed); err != nil {
		return fmt.Errorf("PX-FILE-TRAILER: writing FTR-PAID-LOSS: %w", err)
	}

	if err = w.WriteZonedInt64(p.FtrHashPolicyNumber, 15, codec.SignUnsigned); err != nil {
		return fmt.Errorf("PX-FILE-TRAILER: writing FTR-HASH-POLICY-NUMBER: %w", err)
	}

	if err = w.WriteZonedInt32(p.FtrRunNumber, 4, codec.SignUnsigned); err != nil {
		return fmt.Errorf("PX-FILE-TRAILER: writing FTR-RUN-NUMBER: %w", err)
	}

	switch {
	case p.filler[0] == nil:
		if err = w.WriteBytes(zeroFill[:192]); err != nil {
			return fmt.Errorf("PX-FILE-TRAILER: writing 192 zero bytes for an item the copybook gives no data-name and this record carries none for: %w", err)
		}
	case len(p.filler[0]) != 192:
		return fmt.Errorf("PX-FILE-TRAILER: a writer reports a retained run rather than truncating or padding it, and the run for an item of 192 bytes the copybook gives no data-name is %d", len(p.filler[0]))
	default:
		if err = w.WriteBytes(p.filler[0]); err != nil {
			return fmt.Errorf("PX-FILE-TRAILER: writing the 192 bytes of an item the copybook gives no data-name: %w", err)
		}
	}

	return nil
}
